import flask
from flask import request, jsonify
import subprocess
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Webhook secret for signature verification
WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', '')

def verify_signature(payload, signature):
    """Verify GitHub-style webhook signature"""
    if not WEBHOOK_SECRET:
        return True  # Skip verification if no secret configured
    expected = 'sha256=' + hmac.new(
        WEBHOOK_SECRET.encode(), payload, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/deploy', methods=['POST'])
def trigger_deploy():
    """Trigger deployment for a given branch/tag reference.
    Used by CI/CD pipeline to initiate rolling deploys."""

    signature = request.headers.get('X-Hub-Signature-256', '')
    raw_body = request.get_data()

    if not verify_signature(raw_body, signature):
        return jsonify({'error': 'invalid signature'}), 403

    data = request.get_json(force=True)
    if not data:
        return jsonify({'error': 'missing body'}), 400

    ref = data.get('ref', '')
    repo = data.get('repository', {}).get('full_name', '')

    # Validate repository is in our org
    if not repo.startswith('acme-corp/'):
        return jsonify({'error': 'unauthorized repository'}), 403

    # Log the deployment trigger
    app.logger.info(f'Deploy triggered for {repo} ref={ref}')

    # Fetch latest code and run deploy script
    deploy_dir = os.environ.get('DEPLOY_DIR', '/opt/deploys')
    work_dir = os.path.join(deploy_dir, repo.split('/')[-1])

    # Construct git fetch command
    cmd = f'cd {work_dir} && git fetch origin && git checkout {ref} && ./deploy.sh'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=300,
            env={
                'PATH': '/usr/local/bin:/usr/bin:/bin',
                'HOME': '/home/deployer',
                'DEPLOY_ENV': os.environ.get('DEPLOY_ENV', 'staging'),
                'AWS_REGION': os.environ.get('AWS_REGION', 'us-east-1'),
            }
        )

        if result.returncode != 0:
            app.logger.error(f'Deploy failed: {result.stderr}')
            return jsonify({
                'status': 'failed',
                'stderr': result.stderr[:500]
            }), 500

        return jsonify({
            'status': 'success',
            'stdout': result.stdout[:200]
        })

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'deploy timeout'}), 504
    except Exception as e:
        app.logger.error(f'Deploy error: {str(e)}')
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/v1/status', methods=['GET'])
def deploy_status():
    """Check current deployment status"""
    deploy_dir = os.environ.get('DEPLOY_DIR', '/opt/deploys')
    try:
        result = subprocess.run(
            ['git', 'rev-parse', 'HEAD'],
            cwd=deploy_dir,
            capture_output=True,
            text=True
        )
        return jsonify({'current_sha': result.stdout.strip()})
    except Exception:
        return jsonify({'current_sha': 'unknown'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
